import { createHash, randomUUID } from 'node:crypto'
import { Prisma } from '../../keystone/prisma'

export function trustedClientKey(request:Request,fallback:string){const hops=Number(process.env.TRUSTED_PROXY_HOPS??0);if(!Number.isInteger(hops)||hops<0||hops>5)throw new Error('INVALID_TRUSTED_PROXY_HOPS');if(hops===0)return fallback;const chain=(request.headers.get('x-forwarded-for')??'').split(',').map(value=>value.trim()).filter(Boolean);return chain.length>=hops?chain[chain.length-hops]:fallback}
export const keyHash=(value:string)=>createHash('sha256').update(value).digest('hex')
export async function enforceDurableRate(tx:any,tenantId:string|null,key:string,scope:string,limit:number,windowMs:number){const now=Date.now(),windowStartedAt=new Date(Math.floor(now/windowMs)*windowMs),expiresAt=new Date(windowStartedAt.getTime()+windowMs*2),hash=keyHash(`${scope}:${key}`);const rows=await tx.$queryRaw(Prisma.sql`INSERT INTO "ApiRateBucket" ("id","tenant","keyHash","scope","windowStartedAt","count","expiresAt","createdAt","updatedAt") VALUES (${randomUUID()},${tenantId},${hash},${scope},${windowStartedAt},1,${expiresAt},NOW(),NOW()) ON CONFLICT ((COALESCE("tenant",'')),"keyHash","scope","windowStartedAt") DO UPDATE SET "count"="ApiRateBucket"."count"+1,"expiresAt"=${expiresAt},"updatedAt"=NOW() RETURNING "count"`) as Array<{count:number}>;if((rows[0]?.count??limit+1)>limit)throw new Error('RATE_LIMITED')}
