import { list as keystoneList } from '@keystone-6/core'
import { denyAll } from '@keystone-6/core/access'
import { checkbox, integer, json, relationship, select, text, timestamp } from '@keystone-6/core/fields'
import { currentCapability, currentTenantScope } from '../access'
import { trackingFields } from './trackingFields'

const list = (config: any) => keystoneList({ ...config, ui: { hideNavigation: true, hideCreate: true, hideDelete: true, ...config.ui }, graphql: { ...config.graphql, maxTake: 100 } })
const requiredText = () => text({ validation: { isRequired: true } })
const optionalText = () => text()
const requiredTime = () => timestamp({ validation: { isRequired: true } })
const relation = (ref: string) => relationship({ ref, many: false, validation: { isRequired: true } } as any)
const optionalRelation = (ref: string) => relationship({ ref, many: false })
const tenant = () => relationship({ ref: 'Tenant', many: false, validation: { isRequired: true }, access: { create: denyAll, update: denyAll } } as any)
const status = (values: string[], defaultValue = values[0]) => select({ type: 'enum', options: values.map(value => ({ label: value, value })), defaultValue })
const scopedAccess = (capability: string) => ({ operation: { query: currentCapability(capability), create: denyAll, update: denyAll, delete: denyAll }, filter: { query: currentTenantScope } })
const scoped = (capability: string, fields: Record<string, any>) => list({ access: scopedAccess(capability), fields: { tenant: tenant(), ...fields, ...trackingFields } })
const internal = (fields: Record<string, any>) => list({ access: { operation: { query: denyAll, create: denyAll, update: denyAll, delete: denyAll } }, graphql: { omit: true }, ui: { isHidden: true }, fields: { ...fields, ...trackingFields } })

