import { createHmac, createHash } from 'node:crypto'
import { BlockList, isIP } from 'node:net'
import { lookup } from 'node:dns/promises'
import { request as httpsRequest } from 'node:https'

/** Every outbound delivery is signed with the single platform OUTBOUND_WEBHOOK_SECRET; per-endpoint key resolution is not implemented, so the key id says exactly that. */
export const PLATFORM_WEBHOOK_SIGNING_KEY_ID='platform-outbound-v1'
const MAX_WEBHOOK_PAYLOAD_BYTES=256*1024,MAX_WEBHOOK_RESPONSE_BYTES=65_536,WEBHOOK_DEADLINE_MS=5_000,DNS_DEADLINE_MS=2_000
// Non-public IPv4/IPv6 ranges (RFC 6890 special-purpose registry). IPv4-mapped/NAT64/6to4/Teredo forms are refused outright.
const nonPublic=new BlockList()
for(const [network,prefix] of [['0.0.0.0',8],['10.0.0.0',8],['100.64.0.0',10],['127.0.0.0',8],['169.254.0.0',16],['172.16.0.0',12],['192.0.0.0',24],['192.0.2.0',24],['192.88.99.0',24],['192.168.0.0',16],['198.18.0.0',15],['198.51.100.0',24],['203.0.113.0',24],['224.0.0.0',4],['240.0.0.0',4]] as const)nonPublic.addSubnet(network,prefix,'ipv4')
for(const [network,prefix] of [['::',127],['::ffff:0:0',96],['64:ff9b::',96],['64:ff9b:1::',48],['100::',64],['2001::',23],['2001:db8::',32],['2002::',16],['fc00::',7],['fe80::',10],['fec0::',10],['ff00::',8]] as const)nonPublic.addSubnet(network,prefix,'ipv6')
const privateIp=(address:string)=>{const family=isIP(address);return family===4?nonPublic.check(address,'ipv4'):family===6?nonPublic.check(address,'ipv6'):true}
const bareHost=(hostname:string)=>hostname.startsWith('[')&&hostname.endsWith(']')?hostname.slice(1,-1):hostname
async function resolvePublicAddress(hostname:string){const host=bareHost(hostname),literal=isIP(host);if(literal){if(privateIp(host))throw new Error('PRIVATE_WEBHOOK_DESTINATION');return{address:host,family:literal}}let timer:NodeJS.Timeout|undefined;const records=await Promise.race([lookup(host,{all:true,verbatim:true}),new Promise<never>((_resolve,reject)=>{timer=setTimeout(()=>reject(new Error('WEBHOOK_DNS_TIMEOUT')),DNS_DEADLINE_MS)})]).finally(()=>clearTimeout(timer));if(!records.length||records.some(record=>privateIp(record.address)))throw new Error('PRIVATE_WEBHOOK_DESTINATION');return{address:records[0].address,family:records[0].family}}
export async function validateWebhookDestination(raw:string){let url:URL;try{url=new URL(raw)}catch{throw new Error('INVALID_WEBHOOK_URL')}if(url.protocol!=='https:'||url.username||url.password||(url.port&&url.port!=='443')||url.pathname.length>512||url.search.length>1024)throw new Error('UNSAFE_WEBHOOK_URL');await resolvePublicAddress(url.hostname);const allowlist=(process.env.WEBHOOK_EGRESS_HOSTS??'').split(',').map(value=>value.trim().toLowerCase()).filter(Boolean);if(!allowlist.includes(url.hostname.toLowerCase()))throw new Error('WEBHOOK_HOST_NOT_ALLOWLISTED');return url}
/** POST to the validated address only (DNS answer pinned for the connection, TLS still verified against the original hostname), with a byte-bounded response read and a hard deadline. */
function postPinned(url:URL,pinned:{address:string;family:number},headers:Record<string,string>,raw:string){return new Promise<{status:number;body:Buffer}>((resolve,reject)=>{let settled=false;const finish=(error:Error|null,value?:{status:number;body:Buffer})=>{if(settled)return;settled=true;clearTimeout(deadline);if(error)reject(error);else resolve(value!)};const pinnedLookup=(_host:string,options:any,callback:any)=>options?.all?callback(null,[{address:pinned.address,family:pinned.family}]):callback(null,pinned.address,pinned.family);const req=httpsRequest({protocol:'https:',hostname:bareHost(url.hostname),servername:isIP(bareHost(url.hostname))?undefined:bareHost(url.hostname),port:443,path:`${url.pathname}${url.search}`,method:'POST',lookup:pinnedLookup as any,headers:{...headers,'content-length':String(Buffer.byteLength(raw))}},response=>{const chunks:Buffer[]=[];let size=0;response.on('data',(chunk:Buffer)=>{if(size>=MAX_WEBHOOK_RESPONSE_BYTES)return;const slice=chunk.subarray(0,MAX_WEBHOOK_RESPONSE_BYTES-size);chunks.push(slice);size+=slice.length;if(size>=MAX_WEBHOOK_RESPONSE_BYTES){finish(null,{status:response.statusCode??0,body:Buffer.concat(chunks)});response.destroy()}});response.on('end',()=>finish(null,{status:response.statusCode??0,body:Buffer.concat(chunks)}));response.on('error',error=>finish(error));response.on('close',()=>finish(null,{status:response.statusCode??0,body:Buffer.concat(chunks)}))}),deadline=setTimeout(()=>{finish(new Error('WEBHOOK_TIMEOUT'));req.destroy()},WEBHOOK_DEADLINE_MS);req.on('error',error=>finish(error));req.end(raw)})}
export async function deliverSignedWebhook(input:{url:string;deliveryId:string;eventType:string;eventVersion:string;payload:unknown}){const url=await validateWebhookDestination(input.url),raw=JSON.stringify(input.payload);if(typeof raw!=='string'||Buffer.byteLength(raw)>MAX_WEBHOOK_PAYLOAD_BYTES)throw new Error('WEBHOOK_PAYLOAD_TOO_LARGE');const timestamp=String(Date.now()),secret=process.env.OUTBOUND_WEBHOOK_SECRET;if(!secret||secret.length<32)throw new Error('OUTBOUND_WEBHOOK_SECRET_REQUIRED');const signature=createHmac('sha256',secret).update(timestamp).update('.').update(input.deliveryId).update('.').update(raw).digest('hex'),payloadHash=createHash('sha256').update(raw).digest('hex');const pinned=await resolvePublicAddress(url.hostname),started=Date.now(),response=await postPinned(url,pinned,{'content-type':'application/json','openfront-delivery-id':input.deliveryId,'openfront-event-type':input.eventType,'openfront-event-version':input.eventVersion,'openfront-timestamp':timestamp,'openfront-key-id':PLATFORM_WEBHOOK_SIGNING_KEY_ID,'openfront-signature':signature},raw);return{status:response.status,latencyMs:Date.now()-started,responseHash:createHash('sha256').update(response.body).digest('hex'),signature,payloadHash,keyId:PLATFORM_WEBHOOK_SIGNING_KEY_ID}}
