import { evidenceHash } from '../domain/engine'
export async function appendCustomerAudit(tx:any,input:{tenantId:string;playerId:string;action:string;targetType:string;targetId:string;reason:string;payload:unknown}){await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${input.tenantId}))`;const previous=await tx.auditEvent.findFirst({where:{tenantId:input.tenantId},orderBy:[{createdAt:'desc'},{id:'desc'}]}),payloadHash=evidenceHash(input.payload),hash=evidenceHash({tenantId:input.tenantId,previousHash:previous?.hash??'',actorId:input.playerId,action:input.action,targetType:input.targetType,targetId:input.targetId,reason:input.reason,payloadHash});return tx.auditEvent.create({data:{tenantId:input.tenantId,actorId:input.playerId,action:input.action,targetType:input.targetType,targetId:input.targetId,reason:input.reason,payloadHash,previousHash:previous?.hash??'',hash}})}
