import { createCipheriv, createDecipheriv, createHash, createHmac, randomBytes, timingSafeEqual } from 'node:crypto'
const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
export function base32Encode(input:Uint8Array){let bits=0,value=0,result='';for(const byte of input){value=(value<<8)|byte;bits+=8;while(bits>=5){result+=alphabet[(value>>>(bits-5))&31];bits-=5}}if(bits>0)result+=alphabet[(value<<(5-bits))&31];return result}
function base32Decode(input:string){let bits=0,value=0;const bytes:number[]=[];for(const char of input.replace(/=+$/,'').toUpperCase()){const index=alphabet.indexOf(char);if(index<0)throw new Error('INVALID_BASE32');value=(value<<5)|index;bits+=5;if(bits>=8){bytes.push((value>>>(bits-8))&255);bits-=8}}return Buffer.from(bytes)}
function key(){const value=process.env.PII_ENCRYPTION_KEY??process.env.SESSION_SECRET;if(!value||value.length<32)throw new Error('MFA_ENCRYPTION_KEY_REQUIRED');return createHash('sha256').update(value).digest()}
export function encryptTotpSecret(secret:string){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',key(),iv),data=Buffer.concat([cipher.update(secret,'utf8'),cipher.final()]);return`totp:v1:${iv.toString('base64url')}:${cipher.getAuthTag().toString('base64url')}:${data.toString('base64url')}`}
export function decryptTotpSecret(value:string){const[scope,version,ivText,tagText,dataText]=value.split(':');if(scope!=='totp'||version!=='v1')throw new Error('INVALID_MFA_SECRET');const decipher=createDecipheriv('aes-256-gcm',key(),Buffer.from(ivText,'base64url'));decipher.setAuthTag(Buffer.from(tagText,'base64url'));return Buffer.concat([decipher.update(Buffer.from(dataText,'base64url')),decipher.final()]).toString('utf8')}
export function generateTotpSecret(){return base32Encode(randomBytes(20))}
export function totpCode(secret:string,time=Date.now(),step=30){const counter=BigInt(Math.floor(time/1000/step)),buffer=Buffer.alloc(8);buffer.writeBigUInt64BE(counter);const digest=createHmac('sha1',base32Decode(secret)).update(buffer).digest(),offset=digest[digest.length-1]&15,value=((digest[offset]&127)<<24)|((digest[offset+1]&255)<<16)|((digest[offset+2]&255)<<8)|(digest[offset+3]&255);return String(value%1_000_000).padStart(6,'0')}
export function verifyTotp(secret:string,supplied:string,time=Date.now()){if(!/^\d{6}$/.test(supplied))return false;const actual=Buffer.from(supplied);return[-1,0,1].some(window=>{const expected=Buffer.from(totpCode(secret,time+window*30_000));return expected.length===actual.length&&timingSafeEqual(expected,actual)})}
