const requireUnscopedCapability=async(context:any,capability:string)=>{const itemId=context.session?.itemId;if(!itemId||!hasOperatorMfaAssurance(context.session))throw new Error('Not found');const user=await context.prisma.user.findUnique({where:{id:itemId},include:{role:true}});if(!user?.role?.[capability])throw new Error('Not found');return user}
export const requireTenant=async(context:any,capability:string='canManageSportsbook')=>{const isTrustedInternal=Boolean(context.trustedTenantId&&context.trustedActorId&&context.trustedCapabilities?.includes(capability));if(isTrustedInternal)return context.trustedTenantId as string;const user=await requireUnscopedCapability(context,capability);if(!user.tenantId)throw new Error('Not found');return user.tenantId as string}
export async function lockWagerForSettlement(tx:any,tenantId:string,wagerId:string){const rows=await tx.$queryRaw`SELECT id FROM "Wager" WHERE id = ${wagerId} AND tenant = ${tenantId} FOR UPDATE`;if(!rows.length)throw new Error('Not found')}
export async function assertCurrentSettlement(tx:any,tenantId:string,wagerId:string,settlementId:string){const current=await tx.settlement.findFirst({where:{tenantId,wagerId},orderBy:{version:'desc'}});if(!current||current.id!==settlementId)throw new Error('STALE_SETTLEMENT_CORRECTION');return current}
export const serializable=async(prisma:any,fn:(tx:any)=>Promise<any>)=>{for(let attempt=0;;attempt++){try{return await prisma.$transaction(fn,{isolationLevel:'Serializable'})}catch(error:any){if(attempt>=7||!isRetryableTransactionError(error))throw error;await transactionBackoff(attempt)}}}
const decimalOddsFromAmounts=(gross:bigint,stake:bigint)=>{if(stake<=0n)throw new Error('INVALID_STAKE');const scaled=gross*1_000_000n/stake;return `${scaled/1_000_000n}.${String(scaled%1_000_000n).padStart(6,'0')}`}
const limitPeriodStart=(period:string,now:Date)=>new Date(now.getTime()-(period==='DAILY'?1:period==='WEEKLY'?7:30)*86_400_000)
// Money limits bind amount and currency: only same-currency limits and usage count (no implicit FX).
const stakeLimitFacts=async(tx:any,tenantId:string,playerId:string,now:Date,currency:string)=>{const limits=(await tx.playerLimit.findMany({where:{tenantId,playerId,type:'STAKE',effectiveFrom:{lte:now},OR:[{effectiveTo:null},{effectiveTo:{gt:now}}]}})).filter((limit:any)=>!limit.currency||limit.currency===currency);let selected:{periodLimit:bigint;wageredInPeriod:bigint;remaining:bigint}|null=null;for(const limit of limits){const wagers=await tx.wager.findMany({where:{tenantId,playerId,currency,status:{not:'REJECTED'},createdAt:{gte:limitPeriodStart(limit.period??'DAILY',now)}},select:{stakeMinor:true}});const wageredInPeriod=wagers.reduce((sum:bigint,wager:{stakeMinor:string})=>sum+BigInt(wager.stakeMinor),0n),periodLimit=BigInt(limit.amountMinor),remaining=periodLimit-wageredInPeriod;if(!selected||remaining<selected.remaining)selected={periodLimit,wageredInPeriod,remaining}}return selected}
/** Journal idempotency binds the whole posting: a replay must match type, correlation, reversal target and the exact entry multiset, otherwise it is a conflict (never another posting's receipt). Replays are flagged so callers never re-apply projections. */
const journalEntryFingerprint=(rows:readonly {accountId:string|null;side:string|null;amountMinor?:string;amount?:bigint;currency:string}[])=>rows.map(e=>`${e.accountId}|${e.side}|${e.amountMinor??String(e.amount)}|${e.currency}`).sort().join('\n')
export const postJournal=async(tx:any,tenantId:string,journal:Journal,correlationId:string)=>{ validateJournal(journal); const reversalOfId=journal.reversalOf?((await tx.journalTransaction.findFirst({where:{tenantId,idempotencyKey:journal.reversalOf}}))?.id??null):null; const prior=await tx.journalTransaction.findFirst({where:{tenantId,idempotencyKey:journal.idempotencyKey}}); if(prior){ const priorEntries=await tx.journalEntry.findMany({where:{tenantId,transactionId:prior.id}}); if(prior.type!==journal.type||prior.correlationId!==correlationId||(prior.reversalOfId??null)!==reversalOfId||journalEntryFingerprint(priorEntries)!==journalEntryFingerprint(journal.entries))throw new Error('JOURNAL_IDEMPOTENCY_CONFLICT'); return {...prior,replayed:true} } const posted=await tx.journalTransaction.create({data:{tenantId,type:journal.type,idempotencyKey:journal.idempotencyKey,correlationId,status:'POSTED',effectiveAt:new Date(),reversalOfId}}); await tx.journalEntry.createMany({data:journal.entries.map(e=>({tenantId,transactionId:posted.id,accountId:e.accountId,side:e.side,amountMinor:String(e.amount),currency:e.currency}))}); return posted }
export const appendAudit=async(tx:any,tenantId:string,actorId:string,action:string,targetType:string,targetId:string,reason:string,payload:unknown)=>{await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${tenantId}))`;const previous=await tx.auditEvent.findFirst({where:{tenantId},orderBy:[{createdAt:'desc'},{id:'desc'}]});const payloadHash=evidenceHash(payload);const hash=evidenceHash({tenantId,previousHash:previous?.hash??'',actorId,action,targetType,targetId,reason,payloadHash});return tx.auditEvent.create({data:{tenantId,actorId,action,targetType,targetId,reason,payloadHash,previousHash:previous?.hash??'',hash}})}
// Rejecting a result approval rejects the exact version it bound, so it leaves the pending queue and a new version can be entered.
const rejectApprovedResultVersion=async(tx:any,tenantId:string,actorId:string,approval:{id:string;payloadHash:string;requestPayload?:any},reason:string)=>{const recorded=approval.requestPayload?.resultVersionId;const candidates=await tx.resultVersion.findMany({where:{tenantId,status:'PENDING',...(recorded?{id:String(recorded)}:{})}});const result=candidates.find((item:any)=>{try{return resultApprovalHash(item)===approval.payloadHash}catch{return false}});if(!result)return;const updated=await tx.resultVersion.updateMany({where:{id:result.id,tenantId,status:'PENDING'},data:{status:'REJECTED'}});if(updated.count===1)await appendAudit(tx,tenantId,actorId,'result.rejected','ResultVersion',result.id,reason,{approvalId:approval.id,payloadHash:approval.payloadHash})}
const requireScopedPlayer=async(tx:any,tenantId:string,playerId:string)=>{const player=await tx.player.findFirst({where:{id:playerId,tenantId}});if(!player)throw new Error('Not found');return player}
const parseObject=(value:string,label:string)=>{try{const parsed=JSON.parse(value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error();return parsed}catch{throw new Error(`INVALID_${label}`)}}
export const positiveMoney=(value:string,label:string)=>{if(!/^\d+$/.test(value)||BigInt(value)<=0n)throw new Error(`INVALID_${label}`);return value}
const roleCapabilityKeys=['canAccessDashboard','canManageOnboarding','canManageSportsbook','canTrade','canManageRisk','canManageCompliance','canManageFinance','canManageIntegrations','canApproveSensitiveActions','canReadAudit','canManageRoles','canManagePeople'] as const
const parseRoleCapabilities=(raw:string)=>{let value:unknown;try{value=JSON.parse(raw)}catch{throw new Error('INVALID_CAPABILITIES')}if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('INVALID_CAPABILITIES');const input=value as Record<string,unknown>,result:Record<string,boolean>={};for(const key of Object.keys(input)){if(!roleCapabilityKeys.includes(key as any)||typeof input[key]!=='boolean')throw new Error('INVALID_CAPABILITIES');result[key]=input[key] as boolean}return result}
export const accountMap=async(tx:any,tenantId:string,playerId:string,currency:string)=>{ const rows=await tx.ledgerAccount.findMany({where:{tenantId,currency,OR:[{playerId},{key:{in:['WAGERS_PENDING','GAMING_REVENUE','WINNINGS_EXPENSE','PAYMENT_CLEARING']}}]}}); const map=Object.fromEntries(rows.map((a:any)=>[a.key,a])); for(const key of ['PLAYER_CASH','WAGERS_PENDING','GAMING_REVENUE','WINNINGS_EXPENSE','PAYMENT_CLEARING'])if(!map[key])throw new Error(`MISSING_LEDGER_ACCOUNT:${key}`); return map }

