import type { PrismaClient } from '../../keystone/prisma'

export async function assertOperatorReady(prisma: PrismaClient | any, tenantId: string, request?: Request) {
  if (!tenantId) throw new Error('OPERATOR_NOT_LICENSED')
  const now = new Date()
  const licences = await prisma.operatorLicence.findMany({ where: { tenantId, status: 'ACTIVE', expiresAt: { gt: now } } })
  const licence = licences.find((item: any) => item.licenceNumber && item.regulator && Array.isArray(item.permittedRegions) && item.permittedRegions.length)
  if (!licence) throw new Error('OPERATOR_NOT_LICENSED')
  const payments = await prisma.providerConnection.findFirst({ where: { tenantId, status: 'ACTIVE', adapterId: { in: ['stripe', 'authorizenet', 'paysafe', 'aeropay', 'manual'] } }, select: { id: true } })
  if (!payments) throw new Error('PAYMENTS_NOT_CONFIGURED')
  // Until this vertical exposes a dedicated operator responsible-gaming settings list,
  // active approved policy records are the authoritative readiness evidence.
  const responsible = prisma.jurisdictionPolicyVersion
    ? await prisma.jurisdictionPolicyVersion.findFirst({ where: { tenantId, status: 'ACTIVE' }, select: { id: true } })
    : true
  if (!responsible) throw new Error('RESPONSIBLE_GAMING_NOT_CONFIGURED')
  const region = request?.headers.get('x-vercel-ip-country-region') || request?.headers.get('cf-ipcountry') || request?.headers.get('x-geo-region') || (process.env.NODE_ENV !== 'production' ? process.env.GEO_DEV_REGION : '')
  // A network-level region is enforced whenever the edge supplies one. Behind a host that supplies none (e.g. Railway),
  // location is proven per player by the GeoCheck evidence that every wager and deposit re-reads at commit time.
  if (region && !licence.permittedRegions.includes(region.toUpperCase())) throw new Error('GEO_BLOCKED')
  return licence
}

export function assertSameOrigin(request: Request) {
 const fetchSite=request.headers.get('sec-fetch-site');if(fetchSite&&fetchSite!=='same-origin'&&fetchSite!=='none')throw new Error('ORIGIN_DENIED')
}
